    a=s.find('@app.post("/api/billing/approve")\ndef billing_approve(');b=s.find('@app.post("/api/billing/approve-all-pending")',a);block=s[a:b]
    old='''    for b, _v in rows:\n        b.estado = "APROBADA"\n        b.approved_at = now\n        b.numero_factura = None\n        b.emitted_at = None\n        touched.append(b)''';new='''    for b, _v in rows:\n        b.estado = "EMITIDA"\n        b.approved_at = now\n        b.numero_factura = invoice_number\n        b.emitted_at = now\n        touched.append(b)'''
    if old not in block: raise SystemExit('transición billing no encontrada')
    s=s[:a]+block.replace(old,new,1)+s[b:]
    oldq='''            AzurEmission.clave_acceso.is_not(None),\n            or_(AzurEmission.fecha >= history_from, AzurEmission.estado.in_(["EN_PROCESO", "CONSULTADA", "RECHAZADA"]))''';newq='''            AzurEmission.clave_acceso.is_not(None),\n            AzurEmission.estado.in_(["EN_PROCESO", "CONSULTADA"])'''
    if oldq in s:s=s.replace(oldq,newq,1)
    m='@app.get("/v460/overlay.css")';inj='V476_CSS = r"""'+CSS+'"""\nV476_JS = r"""'+JS+'"""\nV460_OVERLAY_CSS = (V460_OVERLAY_CSS or "") + "\\n" + V476_CSS\nV460_OVERLAY_JS = (V460_OVERLAY_JS or "") + "\\n" + V476_JS\n\n'+m
    if s.count(m)!=1: raise SystemExit('overlay marker')
    return s.replace(m,inj,1)
